export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a19 19 0 0 1 0 18 19 19 0 0 1 0-18"/>',arrow:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><path d="M14 3v6h6M8 13h8M8 17h5"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v1"/>',pause:'<path d="M9 6v12M15 6v12"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',alert:'<path d="m12 3 10 17H2zM12 9v4m0 3v1"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6zM14 5l5 5"/>',back:'<path d="m12 5-7 7 7 7M5 12h15"/>',server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M11 6.5h6M11 17.5h6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>'};
export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]??paths.info}</svg>`;
export const button=(label,action,variant='',ico='',attrs='')=>`<button type="button" class="btn ${variant}" data-action="${esc(action)}" ${attrs}>${ico?icon(ico):''}${esc(label)}</button>`;
export const link=(label,href,variant='',ico='')=>`<a class="btn ${variant}" href="${esc(href)}">${ico?icon(ico):''}${esc(label)}</a>`;
export const badge=(label,tone='neutral',ico='')=>`<span class="badge ${tone}">${ico?icon(ico):'<i></i>'}${esc(label)}</span>`;
export const notice=(title,body,tone='info',actions='')=>`<div class="notice ${tone}">${icon(tone==='warning'||tone==='error'?'alert':tone==='success'?'check':'info')}<div><strong>${esc(title)}</strong>${body?`<p>${esc(body)}</p>`:''}${actions?`<div class="notice-actions">${actions}</div>`:''}</div></div>`;
export const field=(label,id,value='',options={})=>`<label class="field" for="${id}"><span>${esc(label)}${options.optional?` <small>${esc(options.optional)}</small>`:''}</span>${options.area?`<textarea id="${id}" name="${id}" maxlength="${options.max??1000}" placeholder="${esc(options.placeholder??'')}" ${options.readonly?'readonly':''}>${esc(value)}</textarea>`:`<input id="${id}" name="${id}" value="${esc(value)}" maxlength="${options.max??160}" placeholder="${esc(options.placeholder??'')}" ${options.required?'required':''} ${options.readonly?'readonly':''} ${options.autocomplete?'autocomplete="'+options.autocomplete+'"':''}>`}${options.hint?`<small class="field-hint">${esc(options.hint)}</small>`:''}</label>`;
export const picker=(id,label,value,options,cls='')=>`<div class="picker ${cls}"><button type="button" class="picker-trigger" data-picker="${esc(id)}" aria-haspopup="listbox" aria-expanded="false" aria-label="${esc(label)}" data-options="${esc(JSON.stringify(options))}" data-value="${esc(value)}"><span>${esc(options.find(x=>x.value===value)?.label??value)}</span>${icon('down')}</button></div>`;
let currentMenu=null,trigger=null;
export function closePicker(restore=false){currentMenu?.remove();currentMenu=null;if(trigger){trigger.setAttribute('aria-expanded','false');if(restore)trigger.focus();}trigger=null;}
export function togglePicker(el){if(trigger===el){closePicker();return;}closePicker();trigger=el;const options=JSON.parse(el.dataset.options);currentMenu=document.createElement('div');currentMenu.className='picker-menu';currentMenu.setAttribute('role','listbox');currentMenu.setAttribute('aria-label',el.getAttribute('aria-label'));currentMenu.id='active-picker-menu';el.setAttribute('aria-controls',currentMenu.id);el.setAttribute('aria-expanded','true');currentMenu.innerHTML=options.map(o=>`<button type="button" role="option" aria-selected="${o.value===el.dataset.value}" data-pick="${esc(el.dataset.picker)}" data-value="${esc(o.value)}">${icon('check')}<span>${esc(o.label)}${o.detail?`<small>${esc(o.detail)}</small>`:''}</span></button>`).join('');(el.closest('dialog')??document.body).append(currentMenu);const rect=el.getBoundingClientRect();const width=Math.min(Math.max(rect.width,200),window.innerWidth-24);currentMenu.style.width=width+'px';currentMenu.style.left=Math.min(Math.max(12,rect.left),window.innerWidth-width-12)+'px';const height=currentMenu.offsetHeight;currentMenu.style.top=(rect.bottom+height+12>window.innerHeight?Math.max(12,rect.top-height-6):rect.bottom+6)+'px';currentMenu.querySelector('[aria-selected="true"]')?.focus();}
export function pickerKeys(event){if(!currentMenu)return false;if(event.key==='Escape'){event.preventDefault();event.stopPropagation();closePicker(true);return true;}const items=[...currentMenu.querySelectorAll('[role="option"]')];let index=items.indexOf(document.activeElement);if(['ArrowUp','ArrowDown','Home','End'].includes(event.key)){event.preventDefault();index=event.key==='Home'?0:event.key==='End'?items.length-1:(index+(event.key==='ArrowDown'?1:-1)+items.length)%items.length;items[index].focus();return true;}if(event.key==='Tab')closePicker();return false;}
export function openDialog(content){closePicker();const dialog=document.getElementById('modal');dialog.innerHTML=content;if(!dialog.open)dialog.showModal();return dialog;}
export function closeDialog(){closePicker();document.getElementById('modal').close();}
let toastTimer;
export function toast(text){const el=document.getElementById('toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},3800);}
